ALTER POLICY "Media public read" ON storage.objects TO authenticated USING(bucket_id='site-gallery' AND (storage.foldername(name))[1]=public.account_owner()::text);
CREATE FUNCTION public.team_write_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NEW.user_id<>auth.uid() AND (NEW.user_id<>public.account_owner() OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid())) THEN RAISE EXCEPTION 'Sem acesso à conta'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.team_write_guard() FROM PUBLIC;
CREATE POLICY "Team checkout receipts" ON public.transactions FOR INSERT TO authenticated WITH CHECK(user_id=public.account_owner() AND type='receita' AND status='pago' AND ((reservation_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.reservations WHERE id=reservation_id AND user_id=public.account_owner())) OR (order_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.orders WHERE id=order_id AND user_id=public.account_owner()))));
CREATE POLICY "Account admin financial read" ON public.transactions FOR SELECT TO authenticated USING(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin'));